$ErrorActionPreference='Stop'
$root='C:\Sites\svitla-text'
if(!(Test-Path -LiteralPath "$root\app\server.mjs")){throw 'Site not found'}
$backup="$root\backups\text-save-receipt-$(Get-Date -Format yyyyMMdd-HHmmss)"
New-Item -ItemType Directory -Path $backup -Force|Out-Null
$files=ConvertFrom-Json @'
{"admin.html":""}
'@
foreach($p in $files.PSObject.Properties){Copy-Item -LiteralPath "$root\app\$($p.Name)" -Destination "$backup\$($p.Name)"}
try{
 foreach($p in $files.PSObject.Properties){$path="$root\app\$($p.Name)";[IO.File]::WriteAllBytes($path+'.tmp',[Convert]::FromBase64String($p.Value));Move-Item -LiteralPath ($path+'.tmp') -Destination $path -Force}
 $page=Invoke-WebRequest -UseBasicParsing 'http://127.0.0.1:3088/admin' -TimeoutSec 15
 if(!$page.Content.Contains('id="editText"')){throw 'Button check failed'}
 Write-Host 'Updated: text save success receipt enabled. No service restart needed.' -ForegroundColor Green
}catch{
 foreach($p in $files.PSObject.Properties){Copy-Item -LiteralPath "$backup\$($p.Name)" -Destination "$root\app\$($p.Name)" -Force}
 throw
}
